using Luma.Core;using System.Security.Cryptography;using Xunit;namespace Luma.Core.Tests;public sealed class SignedUpdatePolicyTests{[Fact]public void VerifyRejectsTampering(){using var k=ECDsa.Create(ECCurve.NamedCurves.nistP256);var sha=new string('a',64);var p=SignedUpdatePolicy.CanonicalPayload("1.9.11","stable","updates/stable/Luma.zip",sha,123,false,"1.9.10","Новая версия","Исправлены вкладки.\nКнопки.");var s=Convert.ToBase64String(k.SignData(System.Text.Encoding.UTF8.GetBytes(p),HashAlgorithmName.SHA256,DSASignatureFormat.Rfc3279DerSequence));var pem=k.ExportSubjectPublicKeyInfoPem();Assert.True(SignedUpdatePolicy.Verify(pem,s,"1.9.11","stable","updates/stable/Luma.zip",sha,123,false,"1.9.10","Новая версия","Исправлены вкладки.\nКнопки."));Assert.False(SignedUpdatePolicy.Verify(pem,s,"1.9.12","stable","updates/stable/Luma.zip",sha,123,false,"1.9.10","Новая версия","Исправлены вкладки.\nКнопки."));}}
